    if (!is.null(username)) {
      query <- "SELECT 	operation_date, operation_time, document_number,
			operation_description, asset_measurement_unit,
			initial_accounting_method, initial_balance,
			asset_initial_quantity, revaluation_method, revalued_amount,
			asset_revalued_quantity, debit, asset_debit_quantity, credit,
			asset_credit_quantity, correspondence_debit,
			correspondence_credit, final_balance, asset_residual_quantity,
			username
                FROM %s 
                WHERE session_id = $1 AND username = $2 
                ORDER BY id"
    } else {
      query <- "SELECT 	operation_date, operation_time, document_number,
			operation_description, asset_measurement_unit,
			initial_accounting_method, initial_balance,
			asset_initial_quantity, revaluation_method, revalued_amount,
