  conn <- NULL
  tryCatch({
    conn <- create_database_connection()
    if (is.null(conn)) return(NULL)
    query <- "SELECT DISTINCT ON (operation_date, operation_time, document_number, security_type,
                                 security_maturity_period, operation_description, initial_accounting_method)
                     operation_date, operation_time, document_number,
                     security_type, security_maturity_period, operation_description,
                     initial_accounting_method, initial_accounted_quantity,
                     initial_balance, revaluation_method, revalued_asset_quantity,
                     revalued_amount, assets_increase_quantity, debit,
                     assets_decrease_quantity, credit, correspondence_debit,
                     correspondence_credit, final_balance_quantity,
                     final_balance, username
              FROM %s WHERE session_id = $1
              ORDER BY operation_date, operation_time, document_number,
                       security_type, security_maturity_period, operation_description,
                       initial_accounting_method, initial_accounted_quantity,
                       initial_balance, revaluation_method, revalued_asset_quantity,
                       revalued_amount, assets_increase_quantity, debit,
                       assets_decrease_quantity, credit, correspondence_debit,
                       correspondence_credit, final_balance_quantity,
                       final_balance, username, updated_at DESC, id DESC"
    query <- sprintf(query, table_name)
    result <- dbGetQuery(conn, query, params = list(session_id))
    if (nrow(result) == 0) { dbDisconnect(conn); return(NULL) }
    if ("operation_date" %in% names(result)) result$operation_date <- as.character(result$operation_date)
    if ("operation_time" %in% names(result)) result$operation_time <- as.character(result$operation_time)
    dbDisconnect(conn)
    return(result)
  }, error = function(e) { if (!is.null(conn)) try(dbDisconnect(conn), silent = TRUE); return(NULL) })
}

