	  if (is.null(data)) {
	    message("No data to save for table: ", table_name)
	    data <- data.frame()
	  }

	  conn <- NULL
	  tryCatch({
	    conn <- create_database_connection()
	    if (is.null(conn)) {
	      message("Failed to connect to database")
	      return(FALSE)
	    }

	    dbExecute(conn, "BEGIN")

	    message(paste("Saving data to", table_name, "in session", session_id))
	    message(paste("Number of rows to save:", nrow(data)))

	    # Delete existing records for this session
	    delete_query <- sprintf("DELETE FROM %s WHERE session_id = $1", table_name)
	    dbExecute(conn, delete_query, list(session_id))
	    message("Deleted all data for session: ", session_id)

	    # Insert new data if any
	    if (nrow(data) > 0) {
	      insert_query <- sprintf(
	        "INSERT INTO %s
	        	(session_id, username, operation_date,
			operation_time, document_number, debtor_details,
			allowance_account, initial_balance, undue_total_debt,
			undue_current_debt, undue_current_debt_maturity, ecl_undue_debt_method,
			undue_debt_ecl_amount, doubtful_31_90_method, doubtful_31_90_total,
