	        # Handle operation_time: if missing, use current Tashkent time
	        time_val <- as.character(data[[2]][i] %||% NA)
	        if (is.na(time_val) || time_val == "") {
	          time_val <- as.character(lubridate::now("Asia/Tashkent"))
	        }

