	        as.numeric(data[[16]][i] %||% 0),  # doubtful_91_180_total
	        as.numeric(data[[17]][i] %||% 0),  # doubtful_91_180_ecl_amount
	        as.character(data[[18]][i] %||% NA),  # doubtful_181_270_method
	        as.numeric(data[[19]][i] %||% 0),  # doubtful_181_270_total
	        as.numeric(data[[20]][i] %||% 0),  # doubtful_181_270_ecl_amount
