# СПЕЦИАЛИЗИРОВАННЫЕ ФУНКЦИИ ДЛЯ ИНИЦИАЛИЗАЦИИ ТАБЛИЦ

initialize_1010_table <- function(conn) {
  tables <- list(
    app_data_1010 = "
      CREATE TABLE IF NOT EXISTS app_data_1010 (
        id SERIAL PRIMARY KEY,
        session_id VARCHAR(255) NOT NULL,
        operation_date DATE,
        operation_time TIMESTAMP,
        document_number VARCHAR(255),
        operation_description TEXT,
        accounting_method VARCHAR(255),
        initial_balance NUMERIC DEFAULT 0,
        debit NUMERIC DEFAULT 0,
        credit NUMERIC DEFAULT 0,
        correspondence_debit VARCHAR(255),
        correspondence_credit VARCHAR(255),
        final_balance NUMERIC DEFAULT 0,
        username VARCHAR(255),
        updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
      )"
  )
  
  for (table_name in names(tables)) {
    dbExecute(conn, tables[[table_name]])
  }
  
  index_queries <- list("CREATE INDEX IF NOT EXISTS idx_1010_key ON app_data_1010 (session_id, operation_date, operation_time, username, updated_at DESC, id DESC)")
  
  for (index_query in index_queries) {
    try(dbExecute(conn, index_query), silent = TRUE)
  }
  
  return(TRUE)
}

