	  required_cols <- c(	"Дата операции", "Учетный номер", "Величина измерения активов",
				"Метод первоначального учета", "Начальное сальдо оценочного резерва",
				"Количество или другой показатель активов при начальном сальдо",
				"Метод последующего учета (переоценки)",
				"Количество или другой показатель активов при переоценке",
				"Сумма убытков от фактического обесценения", "Сумма ожидаемых убытков",
				"Дебет", "Кредит", "Счет № (дебет)", "Счет № (кредит)")

	  for (col in required_cols) {
	    if (col %in% names(table_data)) {
	      value <- table_data[[col]][1]
	      if (is.na(value) || (is.character(value) && nchar(trimws(value)) == 0)) {
	        return(FALSE)
	      }
	    }
	  }

	  numeric_cols <- c(	"Начальное сальдо оценочного резерва",
				"Количество или другой показатель активов при начальном сальдо",
				"Количество или другой показатель активов при переоценке",
				"Сумма убытков от фактического обесценения", "Сумма ожидаемых убытков",
				"Дебет", "Кредит", "Конечное сальдо оценочного резерва")
	  for (col in numeric_cols) {
	    if (col %in% names(table_data)) {
	      value <- table_data[[col]][1]
	      if (!is.numeric(value) || is.na(value)) {
	        return(FALSE)
	      }
	    }
	  }
	  return(TRUE)
	}

	is_table_complete_1750 <- function(table_data) {
	  if (is.null(table_data) || nrow(table_data) == 0) {
	    return(FALSE)
	  }

	  required_cols <- c(	"Дата операции", "Учетный номер",
				"Вид или другая идентификация прочих краткосрочных активов",
				"Содержание операции",
				"Величина измерения прочих краткосрочных активов",
				"Метод первоначального учета", "Сальдо начальное",
				"Количество или другой показатель прочих краткосрочных активов при начальном сальдо",
				"Метод последующего учета (переоценки)",
				"Последующая (переоцененная) стоимость",
				"Количество или другой показатель прочих краткосрочных активов при их последующей стоимости",
				"Дебет", "Количество или другой показатель увеличения прочих краткосрочных активов",
				"Кредит", "Количество или другой показатель уменьшения прочих краткосрочных активов",
				"Счет № (дебет)", "Счет № (кредит)",
				"Остаточное количество или другой показатель прочих краткосрочных активов")

	  for (col in required_cols) {
	    if (col %in% names(table_data)) {
	      value <- table_data[[col]][1]
	      if (is.na(value) || (is.character(value) && nchar(trimws(value)) == 0)) {
	        return(FALSE)
	      }
	    }
	  }

	  numeric_cols <- c(	"Сальдо начальное",
				"Количество или другой показатель прочих краткосрочных активов при начальном сальдо",
				"Последующая (переоцененная) стоимость",
				"Количество или другой показатель прочих краткосрочных активов при их последующей стоимости",
				"Дебет", "Количество или другой показатель увеличения прочих краткосрочных активов",
				"Кредит", "Количество или другой показатель уменьшения прочих краткосрочных активов", 
				"Сальдо конечное", "Остаточное количество или другой показатель прочих краткосрочных активов")
	  for (col in numeric_cols) {
	    if (col %in% names(table_data)) {
	      value <- table_data[[col]][1]
	      if (!is.numeric(value) || is.na(value)) {
	        return(FALSE)
	      }
	    }
	  }
	  return(TRUE)
	}

	output$session_selector_ui <- renderUI({
	  r$sessions_updated
    
	  sessions <- get_previous_sessions()
	  r$session_list <- sessions
    
	  if (length(sessions) > 0) {
	    display_names <- sessions
	    choices <- setNames(sessions, display_names)
	    choices <- c("Выберите сессию..." = "", choices)
	    } else {
	    choices <- c("Нет доступных сессий" = "")
	}
    
	selectInput("session_selector", label = NULL, 
                choices = choices, width = "100%")
	})

