# Обработчик сохранения таблицы 1010
observeEvent(input$save_table1010, {
  if (!r$user_authenticated) {
    shinyalert("Ошибка", "Для сохранения необходимо авторизоваться.", type = "error")
    return()
  }
  
  if (!r$db_initialized) {
    shinyalert("Ошибка", "База данных недоступна. Невозможно сохранить таблицу.", type = "error")
    return()
  }
  
  current_session <- session_id()
  
  #Обновляем локальные данные из UI-таблицы
  if (!is.null(input$table1010Item1)) {
    tryCatch({
      new_df <- hot_to_r(input$table1010Item1)
      validation_result <- validate_operation_dates(new_df)
      if (!validation_result$valid) {
        data$df1010 <- validation_result$df
      } else {
        data$df1010 <- new_df
      }
    }, error = function(e) {
      message("Ошибка при обновлении данных из таблицы 1010: ", e$message)
    })
  }
  
  # Удаляем из БД все строки с пустым пользователем для текущей сессии
  delete_empty_user_rows("app_data_1010", current_session)
  
  #Фильтруем строки, принадлежащие ТОЛЬКО текущему пользователю
  user_df <- data$df1010[data$df1010$Пользователь == r$current_user, ]
  
  #Сохраняем данные текущего пользователя
  success <- save_data_simple(user_df, "app_data_1010", current_session, r$current_user)
  
  if (success) {
    shinyalert("Успех", paste("Данные таблицы 1010 сохранены для пользователя", r$current_user), type = "success")
    r$data_version <- r$data_version + 1
    
    update_info <- get_last_update(current_session)
    if (!is.null(update_info)) {
      r$current_session_last_update <- update_info$timestamp
    }
  } else {
    shinyalert("Ошибка", "Не удалось сохранить данные таблицы 1010.", type = "error")
  }
})
  
