observeEvent(input$dates1010, {
    start <- ymd(input$dates1010[[1]])
    end <- ymd(input$dates1010[[2]])

 tryCatch({  
  if (start > end) {
    shinyalert("Ошибка при вводе: конечная дата предшествует начальной дате", type = "error")
    updateDateRangeInput(
      session, 
      "dates1010", 
        start = r$start,
        end = r$end
      )
    } else {
      r$start <- input$dates1010[[1]]
      r$end <- input$dates1010[[2]]
    }
   }, error = function(e) {
      updateDateRangeInput(session,
                           "dates1010",
                           start = ymd(Sys.Date()),
                           end = ymd(Sys.Date()))
      shinyalert("Диапазон дат не может быть пустым! Переход на текущую дату.",
                 type = "error")
    })
 }, ignoreInit = TRUE)

  observe({ 
    if (!is.null(input$table1010Item1)) {
      if (!r$user_authenticated) {
        update_auth_status("Для внесения изменений необходимо авторизоваться!", "warning")
        return()
      }
      
      data$df1010 <- hot_to_r(input$table1010Item1)
  
    if (!any(is.na(input$dates1010)) && input$choices1010 == "Выбор по дате операции") {
     	from=as.Date(input$dates1010[1L])
      	to=as.Date(input$dates1010[2L])
      	if (from>to) to = from
      	selectdates1010_1 <- seq.Date(from=from, to=to, by = "day")
      	data$df1010_2 <- data$df1010[as.Date(data$df1010$"Дата операции") %in% selectdates1010_1, ]
    } else if (!is.null(input$text) && input$choices1010 == "Выбор по учетному номеру") {
      	data$df1010_2 <- data$df1010[data$df1010$"Учетный номер" == input$text, ]
    } else if (!is.null(input$dates1010) && !any(is.na(input$dates1010)) && !is.null(input$text) && input$choices1010 == "Выбор по дате операции и учетному номеру") {
     	from=as.Date(input$dates1010[1L])
      	to=as.Date(input$dates1010[2L])
      	if (from>to) to = from
      	selectdates1010_2 <- seq.Date(from=from, to=to, by = "day")
      	data$df1010_2 <- data$df1010[as.Date(data$df1010$"Дата операции") %in% selectdates1010_2 & data$df1010$"Учетный номер" == input$text, ]
    } else {
        selectdates1010_3 <- unique(data$df1010$"Дата операции")
        data$df1010_2 <- data$df1010[data$df1010$"Дата операции" %in% selectdates1010_3, ]
    }
   }
  })  

  output$table1010Item1 <- renderRHandsontable({
    
   data$df1010[, `Сальдо конечное` := data$df1010[[6]] + data$df1010[[7]] - data$df1010[[8]]]

    rhandsontable(data$df1010, colWidths = 150, height = 500, 
                 allowInvalid=FALSE, fixedColumnsLeft = 2, manualColumnResize = TRUE,
                 contextMenu = TRUE, language = 'ru-RU', dragColumns = FALSE) |>
      hot_col(1, dateFormat = "YYYY-MM-DD", type = "date") |>
      hot_col(2, readOnly = TRUE) |>
      hot_col("Пользователь", readOnly = TRUE) |> hot_col("Время проводки", readOnly = TRUE)
  })
  
  output$nested_ui1010 <- renderUI({
    if (input$choices1010 == "Выбор по дате операции") {
      	dateRangeInput("dates1010", "Выберите период времени:",
                     start = Sys.Date(), end = Sys.Date(), separator = "-")
    } else if (input$choices1010 == "Выбор по учетному номеру") {
      	textInput("text", "Укажите Учетный номер:")
    } else if (input$choices1010 == "Выбор по дате операции и учетному номеру") {
      fluidRow(
       	dateRangeInput("dates1010", "Выберите период времени:",
                       start = Sys.Date(), end = Sys.Date(), separator = "-"),
