    start <- ymd(input$dates1110[[1]])
    end <- ymd(input$dates1110[[2]])

 tryCatch({
  if (start > end) {
    shinyalert("Ошибка при вводе: конечная дата предшествует начальной дате", type = "error")
    updateDateRangeInput(
      session, 
      "dates1110", 
        start = r$start,
        end = r$end
      )
    } else {
      r$start <- input$dates1110[[1]]
      r$end <- input$dates1110[[2]]
      }
   }, error = function(e) {
      updateDateRangeInput(session,
                           "dates1110",
                           start = ymd(Sys.Date()),
                           end = ymd(Sys.Date()))
      shinyalert("Диапазон дат не может быть пустым! Переход на текущую дату.",
                 type = "error")
    })
 }, ignoreInit = TRUE)

observe({
    if (!any(is.na(input$dates1110))) {
      from=as.Date(input$dates1110[1L])
      to=as.Date(input$dates1110[2L])
      if (from>to) to = from
      selectdates1111_1_1 <- seq.Date(from=from,
                               to=to, by = "day")
     data$df1111.1_3 <- data$df1111.1[as.Date(data$df1111.1$`Дата операции`) %in% selectdates1111_1_1, ]
    } else {
      selectdates1111_1_2 <- unique(as.Date(data$df1111.1$`Дата операции`))
      data$df1111.1_3 <- data$df1111.1[data$df1111.1$`Дата операции` %in% selectdates1111_1_2, ]
    }
  })

  observe({
    if(!is.null(input$table1111_1Item1) && !any(is.na(input$table1111_1Item1)))
      data$df1111.1_3<- hot_to_r(input$table1111_1Item1)
  })

