observeEvent(input$dates1131, {
    start <- ymd(input$dates1131[[1]])
    end <- ymd(input$dates1131[[2]])

 tryCatch({
  if (start > end) {
    shinyalert("Ошибка при вводе: конечная дата предшествует начальной дате", type = "error")
    updateDateRangeInput(
      session, 
      "dates1131", 
        start = r$start,
        end = r$end
      )
    } else {
      r$start <- input$dates1131[[1]]
      r$end <- input$dates1131[[2]]
      }
   }, error = function(e) {
      updateDateRangeInput(session,
                           "dates1131",
                           start = ymd(Sys.Date()),
                           end = ymd(Sys.Date()))
      shinyalert("Диапазон дат не может быть пустым! Переход на текущую дату.",
                 type = "error")
    })
 }, ignoreInit = TRUE)

