observeEvent(input$dates1141_1, {
    start <- ymd(input$dates1141_1[[1]])
    end <- ymd(input$dates1141_1[[2]])

 tryCatch({  
  if (start > end) {
    shinyalert("Ошибка при вводе: конечная дата предшествует начальной дате", type = "error")
    updateDateRangeInput(
      session, 
      "dates1141_1", 
        start = r$start,
        end = r$end
      )
    } else {
      r$start <- input$dates1141_1[[1]]
      r$end <- input$dates1141_1[[2]]
    }
   }, error = function(e) {
      updateDateRangeInput(session,
                           "dates1141_1",
                           start = ymd(Sys.Date()),
                           end = ymd(Sys.Date()))
      shinyalert("Диапазон дат не может быть пустым! Переход на текущую дату.",
                 type = "error")
    })
}, ignoreInit = TRUE)

          observe({ 
            if (!is.null(input$table1141_1Item1)) {
              if (!r$user_authenticated) {
                update_auth_status("Для внесения изменений необходимо авторизоваться!", "warning")
                return()
              }
              
              data$df1141.1 <- hot_to_r(input$table1141_1Item1)

    if (!any(is.na(input$dates1141_1)) && input$choices1141_1 == "Выбор по дате операции") {
     	from=as.Date(input$dates1141_1[1L])
      	to=as.Date(input$dates1141_1[2L])
      	if (from>to) to = from
      	selectdates1141_1_1 <- seq.Date(from=from, to=to, by = "day")
      	data$df1141.1_2 <- data$df1141.1[as.Date(data$df1141.1$"Дата операции") %in% selectdates1141_1_1, ]
    } else if (!is.null(input$text) && input$choices1141_1 == "Выбор по учетному номеру") {
      	data$df1141.1_2 <- data$df1141.1[data$df1141.1$"Учетный номер" == input$text, ]
    } else if (!is.null(input$text) && input$choices1141_1 == "Выбор вида производного инструмента") {
      	data$df1141.1_2 <- data$df1141.1[data$df1141.1$"Вид производного инструмента" == input$text, ]
    } else if (!is.null(input$dates1141_1) && !any(is.na(input$dates1141_1)) && !is.null(input$text) && input$choices1141_1 == "Выбор по дате операции и учетному номеру") {
     	from=as.Date(input$dates1141_1[1L])
      	to=as.Date(input$dates1141_1[2L])
      	if (from>to) to = from
      	selectdates1141_1_2 <- seq.Date(from=from, to=to, by = "day")
      	data$df1141.1_2 <- data$df1141.1[as.Date(data$df1141.1$"Дата операции") %in% selectdates1141_1_2 & data$df1141.1$"Учетный номер" == input$text, ]
    } else if (!is.null(input$dates1141_1) && !any(is.na(input$dates1141_1)) && !is.null(input$text) && input$choices1141_1 == "Выбор по дате операции и виду производного инструмента") {
     	from=as.Date(input$dates1141_1[1L])
      	to=as.Date(input$dates1141_1[2L])
      	if (from>to) to = from
      	selectdates1141_1_3 <- seq.Date(from=from, to=to, by = "day")
      	data$df1141.1_2 <- data$df1141.1[as.Date(data$df1141.1$"Дата операции") %in% selectdates1141_1_3 & data$df1141.1$"Вид производного инструмента" == input$text, ]
    } else {
        selectdates1141_1_4 <- unique(data$df1141.1$"Дата операции")
        data$df1141.1_2 <- data$df1141.1[data$df1141.1$"Дата операции" %in% selectdates1141_1_4, ]
    }
}
})  

