      	selectdates1170_1 <- seq.Date(from=from, to=to, by = "day")
      	data$df1170_2 <- data$df1170[as.Date(data$df1170$"Дата операции") %in% selectdates1170_1, ]
    } else if (!is.null(input$text) && input$choices1170 == "Выбор по учетному номеру") {
