    } else if (!is.null(input$sub_choice1170) && input$choices1170 == "Выбор по номеру счета, по которому формируется оценочный резерв") {
      	data$df1170_2 <- data$df1170[data$df1170$"Счет №, по которому формируется оценочный резерв" == input$sub_choice1170, ]
    } else if (!is.null(input$dates1170) && !any(is.na(input$dates1170)) && !is.null(input$text) && input$choices1170 == "Выбор по дате операции и учетному номеру") {
     	from=as.Date(input$dates1170[1L])
      	to=as.Date(input$dates1170[2L])
