      	selectdates1170_2 <- seq.Date(from=from, to=to, by = "day")
      	data$df1170_2 <- data$df1170[as.Date(data$df1170$"Дата операции") %in% selectdates1170_2 & data$df1170$"Учетный номер" == input$text, ]
    } else if (!is.null(input$dates1170) && !any(is.na(input$dates1170)) && !is.null(input$sub_choice1170) && input$choices1170 == "Выбор по дате операции и номеру счета, по которому формируется оценочный резерв") {
     	from=as.Date(input$dates1170[1L])
