#1210

observeEvent(input$dates1210, {
    start <- ymd(input$dates1210[[1]])
    end <- ymd(input$dates1210[[2]])

 tryCatch({  
  if (start > end) {
    shinyalert("Ошибка при вводе: конечная дата предшествует начальной дате", type = "error")
    updateDateRangeInput(
      session, 
      "dates1210", 
        start = r$start,
        end = r$end
      )
    } else {
      r$start <- input$dates1210[[1]]
      r$end <- input$dates1210[[2]]
    }
   }, error = function(e) {
      updateDateRangeInput(session,
                           "dates1210",
                           start = ymd(Sys.Date()),
                           end = ymd(Sys.Date()))
      shinyalert("Диапазон дат не может быть пустым! Переход на текущую дату.",
                 type = "error")
    })
}, ignoreInit = TRUE)

  observe({ 
    if (!is.null(input$table1210Item1)) {
      if (!r$user_authenticated) {
        update_auth_status("Для внесения изменений необходимо авторизоваться!", "warning")
        return()
      }
      
      data$df1210 <- hot_to_r(input$table1210Item1)

    if (!any(is.na(input$dates1210)) && input$choices1210 == "Выбор по дате операции") {
     	from=as.Date(input$dates1210[1L])
      	to=as.Date(input$dates1210[2L])
      	if (from>to) to = from
      	selectdates1210_1 <- seq.Date(from=from, to=to, by = "day")
      	data$df1210_2 <- data$df1210[as.Date(data$df1210$"Дата операции") %in% selectdates1210_1, ]
    } else if (!is.null(input$text) && input$choices1210 == "Выбор по учетному номеру") {
      	data$df1210_2 <- data$df1210[data$df1210$"Учетный номер" == input$text, ]
    } else if (!is.null(input$text) && input$choices1210 == "Выбор вида (названия) товаров или услуг по дебиторской задолженности") {
      	data$df1210_2 <- data$df1210[data$df1210$"Вид (название) товаров или услуг по дебиторской задолженности" == input$text, ]
    } else if (!is.null(input$dates1210) && !any(is.na(input$dates1210)) && !is.null(input$text) && input$choices1210 == "Выбор по дате операции и учетному номеру") {
     	from=as.Date(input$dates1210[1L])
      	to=as.Date(input$dates1210[2L])
      	if (from>to) to = from
      	selectdates1210_2 <- seq.Date(from=from, to=to, by = "day")
      	data$df1210_2 <- data$df1210[as.Date(data$df1210$"Дата операции") %in% selectdates1210_2 & data$df1210$"Учетный номер" == input$text, ]
    } else if (!is.null(input$dates1210) && !any(is.na(input$dates1210)) && !is.null(input$text) && input$choices1210 == "Выбор по дате операции и виду (названию) товаров или услуг по дебиторской задолженности") {
     	from=as.Date(input$dates1210[1L])
      	to=as.Date(input$dates1210[2L])
      	if (from>to) to = from
      	selectdates1210_3 <- seq.Date(from=from, to=to, by = "day")
      	data$df1210_2 <- data$df1210[as.Date(data$df1210$"Дата операции") %in% selectdates1210_3 & data$df1210$"Вид (название) товаров или услуг по дебиторской задолженности" == input$text, ]
    } else {
        selectdates1210_4 <- unique(data$df1210$"Дата операции")
        data$df1210_2 <- data$df1210[data$df1210$"Дата операции" %in% selectdates1210_4, ]
    }
}
})  

  output$table1210Item1 <- renderRHandsontable({
    
   data$df1210[, `Сальдо конечное` := ifelse(!is.na(data$df1210[[11]]) & data$df1210[[11]] != 0,
						data$df1210[[11]], data$df1210[[8]] + data$df1210[[13]] - data$df1210[[15]])]

    rhandsontable(data$df1210, colWidths = 150, height = 500, 
                 allowInvalid=FALSE, fixedColumnsLeft = 2, manualColumnResize = TRUE,
                 contextMenu = TRUE, language = 'ru-RU', dragColumns = FALSE) |>
      hot_col(1, dateFormat = "YYYY-MM-DD", type = "date") |>
      hot_col(2, readOnly = TRUE) |>
