observeEvent(input$dates1711, {
    start <- ymd(input$dates1711[[1]])
    end <- ymd(input$dates1711[[2]])

 tryCatch({  
  if (start > end) {
    shinyalert("Ошибка при вводе: конечная дата предшествует начальной дате", type = "error")
    updateDateRangeInput(
      session, 
      "dates1711", 
        start = r$start,
        end = r$end
      )
    } else {
      r$start <- input$dates1711[[1]]
      r$end <- input$dates1711[[2]]
    }
   }, error = function(e) {
      updateDateRangeInput(session,
                           "dates1711",
                           start = ymd(Sys.Date()),
                           end = ymd(Sys.Date()))
      shinyalert("Диапазон дат не может быть пустым! Переход на текущую дату.",
                 type = "error")
    })
}, ignoreInit = TRUE)

  observe({ 
    if (!is.null(input$table1711Item1)) {
      if (!r$user_authenticated) {
        update_auth_status("Для внесения изменений необходимо авторизоваться!", "warning")
        return()
      }
      
      data$df1711 <- hot_to_r(input$table1711Item1)

    if (!any(is.na(input$dates1711)) && input$choices1711 == "Выбор по дате операции") {
     	from=as.Date(input$dates1711[1L])
      	to=as.Date(input$dates1711[2L])
      	if (from>to) to = from
      	selectdates1711_1 <- seq.Date(from=from, to=to, by = "day")
      	data$df1711_2 <- data$df1711[as.Date(data$df1711$"Дата операции") %in% selectdates1711_1, ]
    } else if (!is.null(input$text) && input$choices1711 == "Выбор по учетному номеру") {
      	data$df1711_2 <- data$df1711[data$df1711$"Учетный номер" == input$text, ]
