      	to=as.Date(input$dates1750[2L])
      	if (from>to) to = from
      	selectdates1750_1 <- seq.Date(from=from, to=to, by = "day")
      	data$df1750_2 <- data$df1750[as.Date(data$df1750$"Дата операции") %in% selectdates1750_1, ]
    } else if (!is.null(input$text) && input$choices1750 == "Выбор по учетному номеру") {
      	data$df1750_2 <- data$df1750[data$df1750$"Учетный номер" == input$text, ]
    } else if (!is.null(input$text) && input$choices1750 == "Выбор по идентификации прочих краткосрочных активов") {
      	data$df1750_2 <- data$df1750[data$df1750$"Вид или другая идентификация прочих краткосрочных активов" == input$text, ]
    } else if (!is.null(input$dates1750) && !any(is.na(input$dates1750)) && !is.null(input$text) && input$choices1750 == "Выбор по дате операции и учетному номеру") {
     	from=as.Date(input$dates1750[1L])
      	to=as.Date(input$dates1750[2L])
      	if (from>to) to = from
      	selectdates1750_2 <- seq.Date(from=from, to=to, by = "day")
      	data$df1750_2 <- data$df1750[as.Date(data$df1750$"Дата операции") %in% selectdates1750_2 & data$df1750$"Учетный номер" == input$text, ]
    } else if (!is.null(input$dates1750) && !any(is.na(input$dates1750)) && !is.null(input$text) && input$choices1750 == "Выбор по дате операции и идентификации прочих краткосрочных активов") {
     	from=as.Date(input$dates1750[1L])
      	to=as.Date(input$dates1750[2L])
      	if (from>to) to = from
      	selectdates1750_3 <- seq.Date(from=from, to=to, by = "day")
      	data$df1750_2 <- data$df1750[as.Date(data$df1750$"Дата операции") %in% selectdates1750_3 & data$df1750$"Вид или другая идентификация прочих краткосрочных активов" == input$text, ]
    } else {
        selectdates1750_4 <- unique(data$df1750$"Дата операции")
        data$df1750_2 <- data$df1750[data$df1750$"Дата операции" %in% selectdates1750_4, ]
    }
}
})  

